# -*- coding: utf-8 -*-
"""Healthcare: 235 industries. One concrete marketing fact each."""

H = {}

# --- Hospitals and facilities (20) ---
H["Hospitals"] = "Most hospital search traffic is people looking for a department, a wait time or parking, and the site is usually built around the org chart instead."
H["Teaching and academic hospitals"] = "Research reputation drives referrals and does nothing for the patient searching for an appointment, so the site has to serve both without one burying the other."
H["Children's hospitals"] = "Every search is made by a frightened parent, which makes plain answers about what happens next worth more than any reassurance about excellence."
H["Community and rural hospitals"] = "Competing against urban centres people will drive past you to reach, so the argument is access and wait time rather than capability."
H["Psychiatric hospitals"] = "Platform restrictions on mental health targeting are strictest here, which pushes almost the entire acquisition job into organic search and referral relationships."
H["Rehabilitation hospitals"] = "The referral comes from an acute hospital discharge planner, so the marketing audience is a professional with a caseload, not a patient."
H["Surgical and procedure centres"] = "Wait time is the product. Publishing a real number for how soon a procedure can be scheduled outperforms every other message tested."
H["Urgent care and walk-in clinics"] = "Current wait time is the single most searched piece of information about a walk-in clinic and almost nobody publishes it live."
H["After-hours and emergency clinics"] = "Demand peaks exactly when the phones are least staffed, so ad scheduling and an answered phone matter more than campaign structure."
H["Medical centres and multi-site groups"] = "Locations sharing a single set of campaigns bid against each other, and the group pays extra for the privilege."
H["Community health centres"] = "Funding models limit what can be promoted, so the marketing job is usually awareness of eligibility rather than acquisition."
H["Dialysis centres"] = "Patients attend three times a week for years, so proximity and chair availability decide the choice and nothing else comes close."
H["Infusion clinics"] = "Coverage and prior authorisation questions are the first thing patients ask and the last thing the website answers."
H["Sleep labs"] = "Most volume arrives by physician referral, and the growth lever is turnaround time to the referring doctor rather than consumer advertising."
H["Medical transport and ambulance"] = "Buyers are facilities and insurers on contract, so a strong consumer site is worth less than a page that survives a procurement review."
H["Vaccination and travel clinics"] = "Demand is trip-triggered and seasonal, and the search happens four to eight weeks before departure."
H["Occupational health clinics"] = "Sold to employers on turnaround time and compliance reporting, which means the buyer is an HR or safety manager."
H["Sexual health clinics"] = "Discretion is the conversion factor. Anonymous booking and clear privacy language do more than any messaging about care quality."
H["Plasma and blood donation centres"] = "Compensation and appointment convenience drive donor volume, and retention of existing donors is far cheaper than recruiting new ones."
H["Mobile clinics and health units"] = "Schedule and location change weekly, so the site's job is publishing where the unit will be, accurately and early."

# --- Senior and home care (12) ---
H["Long-term care"] = "Availability changes weekly and families rule out any provider whose website cannot tell them whether there is a bed."
H["Retirement and senior living"] = "Monthly cost is the first question, and communities that publish a starting range get more tours than ones that ask you to call."
H["Memory care"] = "The adult child searching is usually in crisis after an incident, and the decision window is days rather than months."
H["Home care agencies"] = "Hourly rate and minimum shift length are the two things every caller asks, and publishing them filters out the enquiries that were never going to book."
H["Caregiver and PSW agencies"] = "Recruitment and client acquisition compete for the same budget, and staffing is usually the binding constraint."
H["Adult day and respite programs"] = "Caregiver burnout drives the enquiry, so content that speaks to the caregiver converts better than content about the participant."
H["Hospice and palliative care"] = "Search happens at the hardest moment a family will face, and clear, calm information about what happens next matters more than any brand message."
H["Senior transportation"] = "Booking has to work by phone for the rider and online for the adult child arranging it, and most services only build one."
H["Medical alert and monitoring"] = "Bought by an adult child for a parent who did not ask for it, which means the creative has to overcome the parent's objection, not the buyer's."
H["Assisted and independent living"] = "Tours are the conversion event, and the gap between enquiry and booked tour is where most communities lose people."
H["Geriatric care management"] = "A service most families do not know exists, so the search volume is small and the content job is explaining the category."
H["Home accessibility and mobility fit-outs"] = "Triggered by a fall or a discharge, funded partly by grants, and the grant question is what the website needs to answer first."

# --- Medical and surgical specialties (40) ---
H["Family medicine and primary care"] = "Most practices are closed to new patients, so the marketing question is usually roster management rather than acquisition."
H["Concierge and direct primary care"] = "Selling an annual fee against free public care, which makes the entire argument about access and appointment length."
H["Cardiology"] = "Referral driven with a growing share of patients researching the cardiologist afterwards, and the biography page carries that decision."
H["Dermatology"] = "Medical and cosmetic dermatology need separate pages and separate campaigns because the buyers, budgets and platform rules are completely different."
H["Endocrinology and diabetes care"] = "GLP-1 demand has changed the search landscape entirely, and the compliance constraints on advertising it are tightening."
H["Gastroenterology"] = "Colonoscopy screening demand responds to age-based targeting better than almost any other procedure in medicine."
H["Hepatology"] = "Narrow, referral led, and the useful marketing asset is clear content for referring physicians rather than patients."
H["Neurology"] = "Long wait times are the category norm, so publishing a realistic one is a differentiator rather than an admission."
H["Neurosurgery"] = "Patients travel for the surgeon, which makes individual surgeon profiles and outcome context the highest value pages on the site."
H["Oncology"] = "Advertising is heavily restricted and any outcome claim is a serious risk, so the entire program runs on organic content and referral relationships."
H["Hematology"] = "Small patient populations and physician-driven referral, so search volume is low and the content should be written for clinicians."
H["Infectious disease"] = "Demand is event driven and unpredictable, which makes standing organic content far more valuable than campaigns."
H["Geriatrics"] = "The adult child is doing the searching, and content addressed to them converts better than content addressed to the patient."
H["OB-GYN and women's health"] = "Patients choose a provider they expect to see for years, so the practitioner biography does more work than the practice description."
H["Fertility and IVF"] = "Cost and success rates are the two questions, both are regulated in how they can be presented, and firms that publish clear pricing get more consultations."
H["Pediatrics"] = "Parents choose on availability and how quickly a sick child can be seen, not on philosophy of care."
H["Psychiatry"] = "Wait times of several months are normal, and publishing yours honestly keeps enquiries warm instead of losing them to a competitor who did."
H["Pulmonology and respirology"] = "Sleep apnea and CPAP demand behaves like a consumer category while the rest of the practice is referral driven."
H["Rheumatology"] = "Long diagnostic journeys mean patients arrive having already researched extensively, so content has to be more specific than the usual overview."
H["Nephrology"] = "Almost entirely referral driven, and the marketing that matters is communication quality back to the referring physician."
H["Urology"] = "Men delay seeking care for years, and discreet, direct content about specific symptoms outperforms general practice messaging."
H["ENT and otolaryngology"] = "Split between routine referral work and elective procedures like septoplasty that behave like cosmetic purchases."
H["Allergy and immunology"] = "Sharply seasonal search demand that spikes with pollen counts and collapses between seasons."
H["Sports medicine"] = "Athletes and active patients research the practitioner, and association with a team or club carries more weight than any credential list."
H["Pain management"] = "Advertising restrictions around opioids and pain treatment are significant, and copy has to describe assessment rather than relief."
H["Sleep medicine"] = "Patients arrive already suspecting the diagnosis, so content that explains the study process and cost converts better than symptom awareness content."
H["CPAP and sleep apnea clinics"] = "Equipment sales and clinical service have different economics, and blending them in the reporting hides which one is working."
H["Bariatric and weight medicine"] = "The most heavily restricted advertising category in healthcare, where before and after imagery and outcome claims are both prohibited."
H["Vein and vascular clinics"] = "Cosmetic and medical vein treatment sit under different insurance and advertising rules, and mixing them on one page satisfies neither."
H["Thoracic surgery"] = "Referral driven and surgeon specific, where the useful asset is a credible profile rather than a service page."
H["Colorectal surgery"] = "Screening awareness drives volume, and age-targeted campaigns perform where general awareness campaigns do not."
H["Transplant programs"] = "Referral relationships with regional centres carry the volume, and outcome data is published under strict reporting rules."
H["Orthopedics"] = "Joint replacement wait times drive patients to travel, and publishing a realistic surgical date wins consultations."
H["Hand and upper limb clinics"] = "Workplace injury and insurance referral drive much of the volume, so the audience includes adjusters and case managers."
H["Plastic and cosmetic surgery"] = "Before and after imagery is restricted on the platforms that drive the category, which forces the creative onto process, credentials and consultation."
H["Wound care clinics"] = "Referral from home care and long-term care providers, with turnaround and reporting quality as the selling points."
H["Hyperbaric oxygen therapy"] = "Approved indications are narrow and claims beyond them attract regulatory attention quickly."
H["Lymphedema clinics"] = "Small patient population, high loyalty, and coverage questions dominating every first conversation."
H["Genetics and genomic testing"] = "Direct to consumer and clinical testing face different rules, and conflating them in marketing creates a compliance problem."
H["Medico-legal and IME providers"] = "The buyers are lawyers and insurers, so the site is a business to business asset and consumer messaging is wasted."

# --- Maternal and newborn care (6) ---
H["Maternity and prenatal clinics"] = "The decision window opens with a positive test and closes at delivery, which is one of the few genuinely predictable timelines in healthcare."
H["Birth centres"] = "Competing against free hospital birth, so the argument is experience and continuity rather than safety, which cannot be claimed comparatively."
H["Prenatal imaging and 3D ultrasound"] = "A discretionary, gift-like purchase with a narrow gestational window, which makes timing the targeting the whole job."
H["Maternal and perinatal mental health"] = "Platform restrictions on mental health targeting apply fully, and the audience is reached through partner referral more reliably than through ads."
H["Midwifery and doulas"] = "Chosen through local parent communities and word of mouth, where reviews and recommendations outweigh any advertising."
H["Lactation and postpartum support"] = "Urgent need in the first two weeks after birth, so same-day availability is the message that converts."

# --- Pediatric and child health (6) ---
H["Pediatric centres and children's clinics"] = "Parents choose on how fast a sick child can be seen, and publishing same-day availability beats every other message."
H["Pediatric urgent care"] = "Peak demand is evenings and weekends, and campaigns scheduled for business hours miss most of it."
H["Children's therapy centres"] = "Waitlists run months, and the practices that publish honest wait times keep families who come back when a space opens."
H["Child development and assessment centres"] = "Assessment cost and whether it is covered are the deciding questions, and most sites answer neither."
H["Child and youth mental health"] = "Targeting restrictions are absolute here, so all reach comes through parent-directed content and school or physician referral."
H["Children's vision and optometry"] = "School vision screening failures drive the enquiry, which makes the back-to-school window disproportionately valuable."

# --- Dental (12) ---
H["General dentistry"] = "Insurance acceptance is the first filter for most patients, and practices that list their accepted plans get more calls than ones that say they accept most."
H["Cosmetic dentistry and veneers"] = "A considered purchase researched for months, where financing availability moves more consultations than price reductions."
H["Orthodontics and aligners"] = "Competing against direct to consumer aligner brands on price, which makes supervised treatment and included refinements the argument."
H["Periodontics and implants"] = "High ticket, referral led, and the patient usually needs the cost explained in a way the referring dentist did not."
H["Endodontics"] = "Almost entirely referral driven and urgent, so availability communicated to referring practices matters more than consumer advertising."
H["Oral and maxillofacial surgery"] = "Wisdom teeth demand is seasonal around school breaks, and the rest of the practice runs on specialist referral."
H["Pediatric dentistry"] = "Parents choose on how the practice handles an anxious child, and content showing that is worth more than clinical credentials."
H["Sedation and emergency dentistry"] = "Emergency searches happen at night and on weekends, and paying for those clicks without an answered phone is pure waste."
H["Dental sleep medicine"] = "A crossover category where the patient found you through a sleep search, so the content has to bridge two vocabularies."
H["Denturists"] = "An older patient base that still prefers phone contact, which makes a prominent phone number and call tracking more important than form optimisation."
H["Dental hygiene clinics"] = "An independent model many patients do not know exists, so the content job is explaining the category before selling the practice."
H["Dental groups and DSOs"] = "Location pages that differ only by city name rank badly, and most groups have dozens of them."

# --- Eye and vision (8) ---
H["Optometry"] = "Competing with retail chains on exam price, where insurance clarity and appointment availability win more bookings than eyewear selection."
H["Ophthalmology"] = "Referral driven for medical work and consumer driven for elective surgery, which needs two different sets of pages."
H["LASIK and refractive surgery"] = "Headline prices are usually per eye and exclude aftercare, and buyers have learned to distrust them, so publishing the full cost is a differentiator."
H["Cataract surgery"] = "Public wait times drive patients toward private options, and the honest comparison of wait and cost is the content that converts."
H["Retina clinics"] = "Urgent referral from optometrists, so the relationship and turnaround time to those practices is the growth channel."
H["Dry eye clinics"] = "Patients arrive after years of failed self-treatment, so content that explains why previous attempts did not work outperforms service descriptions."
H["Vision therapy and low vision"] = "Parents and adult children searching on behalf of someone else, and the category needs explaining before the practice does."
H["Opticians and eyewear retail"] = "Online eyewear competes on price and return policy, so in-person fitting and adjustment is the argument that holds."

# --- Hearing (3) ---
H["Audiology and hearing clinics"] = "The free hearing test is the conversion event, because it is the low commitment step someone in denial will actually take."
H["Hearing aid retail groups"] = "Device pricing is publicly compared and commoditising, so the durable position is the fitting and the follow-up care."
H["Tinnitus clinics"] = "Sufferers search obsessively and have usually been told nothing can be done, which makes honest content about what management involves unusually effective."

